package fr.roadguard.app;
import android.app.*;import android.content.*;import android.content.pm.*;import android.os.Bundle;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={26,36},application=Application.class)
public class RuntimeManifestContractTest {
 @Test public void radarDownloadIsAResolvablePrivateActivity()throws Exception{Context c=RuntimeEnvironment.getApplication();ActivityInfo info=c.getPackageManager().getActivityInfo(new ComponentName(c,RadarDownloadActivity.class),0);assertFalse(info.exported);assertEquals(RadarDownloadActivity.class.getName(),new Intent(c,RadarDownloadActivity.class).resolveActivity(c.getPackageManager()).getClassName());}
 @Test public void commonServicesAndUpdateProviderSurviveAndroidAutoOverlay()throws Exception{Context c=RuntimeEnvironment.getApplication();PackageManager pm=c.getPackageManager();for(Class<?> type:new Class<?>[]{MapPackDownloadService.class,BackgroundAlertService.class,CarLocationService.class,SpotifySessionListener.class})assertNotNull(pm.getServiceInfo(new ComponentName(c,type),0));ProviderInfo p=pm.getProviderInfo(new ComponentName(c,UpdateApkProvider.class),0);assertEquals(c.getPackageName()+".roadguard.updates",p.authority);assertTrue(p.grantUriPermissions);assertFalse(p.exported);java.util.List<String> permissions=java.util.Arrays.asList(pm.getPackageInfo(c.getPackageName(),PackageManager.GET_PERMISSIONS).requestedPermissions);assertTrue(permissions.contains("android.permission.REQUEST_INSTALL_PACKAGES"));assertTrue(permissions.contains("android.permission.MODIFY_AUDIO_SETTINGS"));assertTrue(permissions.contains("android.permission.FOREGROUND_SERVICE_DATA_SYNC"));}
 @Test public void androidAutoServiceIsDeclaredWhenItsCodeIsIncluded()throws Exception{Class<?> car;try{car=Class.forName("fr.roadguard.app.RoadguardCarAppService");}catch(ClassNotFoundException phoneOnly){return;}Context c=RuntimeEnvironment.getApplication();assertTrue(c.getPackageManager().getServiceInfo(new ComponentName(c,car),0).exported);}
}
